import sys
from functools import lru_cache

def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])
    strengths = sorted([int(x) for x in lines[1].split()], reverse=True)

    m = int(lines[2])
    actions = []
    for i in range(m):
        parts = lines[3 + i].split()
        actions.append((parts[0], int(parts[1])))

    team_state = [0, 0]

    @lru_cache(maxsize=None)
    def minimax(action_idx, available):
        if action_idx == m:
            return team_state[0] - team_state[1]

        action_type, team = actions[action_idx]

        if action_type == 'b':
            # Ban: choose to ban a hero to minimize opponent's advantage
            banned = -1
            if team == 1:
                # Team 1 wants to minimize (team1 - team2), so maximizes (team2 - team1)
                best_val = float('inf')
                for i in available:
                    if i >= len(strengths):
                        continue
                    new_available = available & ((1 << len(strengths)) - (1 << i))
                    if new_available != available:
                        val = -minimax(action_idx + 1, new_available)
                        best_val = min(best_val, val)
                return team_state[0] - team_state[1] + best_val
            else:
                # Team 2 wants to minimize (team1 - team2), so wants to maximize (team2 - team1)
                best_val = float('-inf')
                for i in available:
                    if i >= len(strengths):
                        continue
                    new_available = available & ((1 << len(strengths)) - (1 << i))
                    if new_available != available:
                        val = -minimax(action_idx + 1, new_available)
                        best_val = max(best_val, val)
                return team_state[0] - team_state[1] + best_val

        elif action_type == 'p':
            # Pick: choose to pick a hero
            if team == 1:
                # Team 1 wants to maximize (team1 - team2)
                best_val = float('-inf')
                for i in available:
                    if i >= len(strengths):
                        continue
                    team_state[0] += strengths[i]
                    new_available = available & ((1 << len(strengths)) - (1 << i))
                    if i == available.bit_count() - 1 or i < available.bit_count() - 1:
                        new_available = available & ~((1 << (i + 1)) - 1)
                        best_val = min(best_val, minimax(action_idx + 1, new_available))
                    else:
                        val = minimax(action_idx + 1, new_available)
                        best_val = max(best_val, val)
                    team_state[0] -= strengths[i]
                return best_val
            else:
                # Team 2 wants to maximize (team2 - team1) = minimize (team1 - team2)
                best_val = float('inf')
                for i in available:
                    if i >= len(strengths):
                        continue
                    team_state[1] += strengths[i]
                    new_available = available & ((1 << len(strengths)) - (1 << i))
                    val = minimax(action_idx + 1, new_available)
                    best_val = min(best_val, val)
                    team_state[1] -= strengths[i]
                return best_val

    result = minimax(0, (1 << len(strengths)) - 1)
    return str(result)
