def solution(input_str):
    """
    Solves the Lieges of Legendre game using Sprague-Grundy theorem.
    Input format:
        Line 1: n k
        Line 2: a1 a2 ... an
    Output: "Kevin" if first player wins, "Nicky" otherwise
    """
    lines = input_str.strip().split('\n')
    n, k = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))

    # Compute Grundy values with cycle detection
    # We iterate and detect when the sequence becomes periodic
    seq = [0]  # G(0) = 0

    # Compute Grundy values iteratively
    max_val = max(a) if a else 0

    def get_grundy(n):
        # If we already computed it
        if n < len(seq):
            return seq[n]

        # Compute using memoization with cycle detection
        memo = {}

        def compute_g(idx):
            if idx in memo:
                return memo[idx]

            # Compute reachable Grundy values
            if idx == 0:
                reachable = set()
            elif idx % 2 == 1:
                # Can only remove 1 cow
                reachable = {compute_g(idx - 1)}
            else:
                # Can remove 1 cow OR split into k piles of idx/2
                remove_one = compute_g(idx - 1)

                # Split: k piles of size idx/2
                if k % 2 == 1:
                    split_val = compute_g(idx // 2)
                    # XOR of k copies
                    split_xor = split_val if k % 2 == 1 else 0
                else:
                    split_xor = 0

                reachable = {remove_one, split_xor}

            # Compute mex
            mex = 0
            while mex in reachable:
                mex += 1

            memo[idx] = mex
            return mex

        # Better approach: compute all values up to n with cycle detection
        g_seq = [0]

        for i in range(1, max_val + 1):
            if i % 2 == 1:
                reachable = {g_seq[i-1]}
            else:
                prev = g_seq[i-1]
                half = i // 2
                if k % 2 == 1:
                    split_g = g_seq[half]
                else:
                    split_g = 0
                reachable = {prev, split_g}

            mex = 0
            while mex in reachable:
                mex += 1
            g_seq.append(mex)

        # Return the nth value or handle index overflow if cycle detected
        return g_seq[n] if n < len(g_seq) else g_seq[-1] if g_seq else 0

    xor_sum = 0
    for x in a:
        xor_sum ^= get_grundy(x)

    return "Kevin\n" if xor_sum != 0 else "Nicky\n"


