Looking at this problem, I need to:
1. Find a path from top-left to bottom-right moving only right/down
2. Minimize trailing zeros in the product of all numbers along the path

The key insight: trailing zeros depend on the minimum of total factors of 2 and 5 in the prime factorization of the product. This is a dynamic programming problem where I track Pareto-optimal paths (paths where no path strictly has ≤ factors of both 2 and 5).

```python
def solution(input_str):
    import sys

    lines = input_str.strip().split('\n')
    n = int(lines[0])
    matrix = []
    for i in range(1, n + 1):
        matrix.append(list(map(int, lines[i].split())))

    def count_factors(num, factor):
        """Count factors of 'factor' in num"""
        if num == 0:
            return float('inf')  # Zero = infinite factors
        count = 0
        temp = num
        while temp > 0 and temp % factor == 0:
            count += 1
            temp //= factor
        return count

    # DP: dp[i][j] = list of (sum_2, sum_5) pairs that are Pareto-optimal
    dp = [[None for _ in range(n)] for _ in range(n)]
    path_map = [[None for _ in range(n)] for _ in range(n)]

    # Starting cell
    dp[0][0] = [(count_factors(matrix[0][0], 2), count_factors(matrix[0][0], 5))]
    path_map[0][0] = ''

    def filter_optimal(candidates):
        """Keep only Pareto-optimal pairs - no pair should dominate another"""
        if not candidates:
            return []
        # Sort first by sum_2, then sum_5
        sorted_pairs = sorted(candidates)
        result = []
        for s2, s5 in sorted_pairs:
            # A pair is dominated if we already have a pair with <= both values
            is_dominated = False
            for existing_s2, existing_s5 in result:
                if existing_s2 <= s2 and existing_s5 <= s5:
                    is_dominated = True
                    break
            if not is_dominated:
                result.append((s2, s5))
        return result

    for i in range(n):
        for j in range(n):
            if i == 0 and j == 0:
                continue

            v2 = count_factors(matrix[i][j], 2)
            v5 = count_factors(matrix[i][j], 5)

            candidates = []
            candidate_path = ''

            # From top
            if i > 0 and dp[i - 1][j] is not None:
                for p2, p5 in dp[i - 1][j]:
                    candidates.append((p2 + v2, p5 + v5))
                if candidates:
                    candidate_path = 'D'

            # From left  
            if j > 0 and dp[i][j - 1] is not None:
                for p2, p5 in dp[i][j - 1]:
                    candidates.append((p2 + v2, p5 + v5))
                if candidates:
                    candidate_path = 'R'

            dp[i][j] = filter_optimal(candidates) if candidates else None
            if dp[i][j]:
                path_map[i][j] = candidate_path

    # Find best result
    if dp[n - 1][n - 1] is None or not dp[n - 1][n - 1]:
        return "-1\n"

    best = min(dp[n - 1][n - 1], key=lambda x: min(x[0], x[1]))
    min_zeros = min(best[0], best[1])

    # Reconstruct path by backtracking
    path = [None] * (2 * n - 2)
    i, j = n - 1, n - 1
    while i > 0 or j > 0:
        target_2, target_5 = best[0], best[1]

        # Find which parent cell matches
        from_top = False
        from_left = False

        if i > 0 and dp[i-1][j] and (target_2, target_5) in dp[i-1][j]:
            from_top, path_map[i][j] = True, 'D'
        elif j > 0 and dp[i][j-1] and (target_2, target_5) in dp[i][j-1]:
            from_left, path_map[i][j] = True, 'R'

        if from_top:
            i -= 1
        elif from_left:
            j -= 1
        else:
            # Fallback: check all parents
            if i > 0 and dp[i-1][j]:
                for p2, p5 in dp[i-1][j]:
                    if p2 + count_factors(matrix[i][j], 2) == target_2:
                        i -= 1
                        from_top = True
                        break
            if not from_top and j > 0 and dp[i][j-1]:
                for p2, p5 in dp[i][j-1]:
                    if p2 + count_factors(matrix[i][j], 2) == target_2:
                        j -= 1
                        from_left = True
                        break

        if j > 0 and dp[i][j-1] and (target_2, target_5) in dp[i][j-1] and not from_top:
            j -= 1

    # Reconstruct using dynamic backtracking
    result = []
    i, j = n - 1, n - 1
    while i > 0 or j > 0:
        if dp[i][j] == dp[i-1][j]:
            result.append('D')
            i -= 1
        elif dp[i][j] == dp[i][j-1]:
            result.append('R')
            j -= 1
        else:
            # Find actual parent
            if i > 0 and dp[i-1][j] and target_2 - count_factors(matrix[i][j], 2) in [x[0] for x in dp[i-1][j]]:
                result.append('D')
                i -= 1
            else:
                result.append('R')
                j -= 1

    result.reverse()

    return f"{min_zeros}\n{''.join(result)}"


