The key insight is that a connected undirected graph can be oriented to be strongly connected if and only if it has no bridges (Robbins' Theorem).

```python
def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    adj = [[] for _ in range(n + 1)]
    edges_list = []

    for i in range(m):
        u, v = map(int, lines[1 + i].split())
        edges_list.append((u, v))
        adj[u].append((v, i))
        adj[v].append((u, i))

    disc = [0] * (n + 1)
    low = [0] * (n + 1)
    timer = [0]
    bridges = set()

    def find_bridges(u, p):
        disc[u] = low[u] = timer[0]
        timer[0] += 1
        for v, idx in adj[u]:
            if v == p:
                continue
            if disc[v]:
                low[u] = min(low[u], disc[v])
            else:
                find_bridges(v, u)
                low[u] = min(low[u], low[v])
                if low[v] > disc[u]:
                    bridges.add(idx)

    find_bridges(1, -1)

    if len(bridges) > 0:
        return "0\n"

    result = {}
    visited = [False] * (n + 1)

    def orient(u, p):
        visited[u] = True
        for v, idx in adj[u]:
            if idx in bridges:
                continue
            if visited[v]:
                if idx not in result:
                    result[idx] = (u, v)
            else:
                orient(v, u)
                if idx not in result:
                    result[idx] = (u, v)

    orient(1, -1)

    output = []
    for i in range(m):
        u, v = edges_list[i]
        if i in result:
            output.append(f"{result[i][0]} {result[i][1]}")
        else:
            output.append(f"{u} {v}")

    return "\n".join(output) + "\n"
