        if d > dist[u]:
            continue
        for v, x in adj[u]:
            if dist[u] + x < dist[v]:
                dist[v] = dist[u] + x
                heapq.heappush(pq, (dist[v], v))

    roads_dist = [INF] * (n + 1)
    roads_dist[1] = 0
    pq = [(0, 1)]

