        for v, x in adj[u]:
            if roads_dist[u] + x < roads_dist[v]:
                roads_dist[v] = roads_dist[u] + x
                heapq.heappush(pq, (roads_dist[v], v))

    for s, y in train_routes:
        if y < dist[s]:
            dist[s] = y
        if y < roads_dist[s]:
            roads_dist[s] = y

    ans = 0
    for s, y in train_routes:
