    # Check if edge i and edge j cross
    def is_crossing(i, j):
        if i == j:
            return False
        a1, b1 = edges[i]
        a2, b2 = edges[j]

        # Check if endpoints interleave
        # Normalize: check if exactly one of a2, b2 is in the arc from a1 to b1

        def in_arc(a, b, x):
            """Check if x is in the clockwise arc from a to b (exclusive of endpoints)"""
            if a < b:
                return a < x < b
            else:
                return x > b or x < a

        # Edge crossing condition: one endpoint of second edge in first's arc,
        # and other endpoint not in first's arc
        c_in_a = in_arc(a1, b1, a2)
        d_in_a = in_arc(a1, b1, b2)
        return c_in_a != d_in_a

    # Build 2-SAT implication graph
    # Variable 2*i: edge i is inside ('i')
    # Variable 2*i+1: edge i is outside ('o')
    graph = [[] for _ in range(2 * m)]

    for i in range(m):
        for j in range(i + 1, m):
            if is_crossing(i, j):
                # If edge i is inside, edge j must be outside
                # If edge i is outside, edge j must be inside
                # If edge j is inside, edge i must be outside
                # If edge j is outside, edge i must be inside

                graph[2 * i].append(2 * j + 1)   # i_inside => j_outside
                graph[2 * j + 1].append(2 * i)   # j_outside => i_inside
                graph[2 * i + 1].append(2 * j)   # i_outside => j_inside
                graph[2 * j].append(2 * i + 1)   # j_inside => i_outside

    # 2-SAT solver using SCC
    def solve_2sat(n):
        if n == 0:
            return [True] * 0

        g = [[] for _ in range(2 * n)]
        r = [[] for _ in range(2 * n)]  # reverse graph

        for u in range(2 * n):
            for v in graph[u]:
                if v != u:
                    g[u].append(v)
                    r[v].append(u)

        visited = [False] * (2 * n)
        order = []

        def dfs1(u):
            visited[u] = True
            for v in g[u]:
                if not visited[v]:
                    dfs1(v)
            order.append(u)

        for i in range(2 * n):
            if not visited[i]:
                dfs1(i)

        scc = [-1] * (2 * n)
        scc_cnt = 0
        on_stack = [False] * (2 * n)

        def dfs2(u, stack):
            scc[u] = scc_cnt
            for v in r[u]:
                if scc[v] == -1:
                    dfs2(v, stack)
            stack[u] = True

        def dfs3(u, comp_id):
            stack[u] = False
            scc[u] = comp_id
            for v in r[u]:
                if scc[v] == -1:
                    dfs3(v, comp_id)

        # Kosaraju's algorithm
        stack = []
        for i in range(2 * n):
            if scc[i] == -1:
                dfs2(i, stack)

        comp = [-1] * (2 * n)
        for i in range(2 * n):
            if scc[i] == -1:
                dfs3(scc[i], comp)

        # Check for contradiction
        possible = True
        ans = [False] * n  # True = inside (variable 2*i assigned True)

        for i in range(n):
            if comp[2 * i] == comp[2 * i + 1]:
                possible = False
                return []

        if possible:
            for i in range(n):
                if comp[2 * i] < comp[2 * i + 1]:
                    ans[i] = True  # edge i inside
                else:
                    ans[i] = False  # edge i outside

        res = []
        for x in ans:
            res.append('i' if x else 'o')
        return ''.join(res)

    return solve_2sat(m)
